/*
 * MegaNetAssistantAd — 1080x1920 @30fps, ~16s.
 * Voice: public/voiceover-assistant.mp3 (en-NG-AbeoNeural), word timings in
 * src/assistantTimings.ts (both generated by scripts/assistant_voice.py).
 *
 * Safe area: all content inside x 80-920, y 200-1440; captions end at y=1436.
 * Full-bleed gradient backgrounds + decor live in <Backgrounds/> only, so the
 * `mode: 'bg'` render (backgrounds only) can be diffed against the full render
 * to prove no content pixel leaves the safe area (scripts/check_safe_area.py).
 *
 * No figures, names or statistics: answer cards use placeholder bars only.
 */
import React from 'react';
import {AbsoluteFill, Audio, Easing, Img, Sequence, interpolate, staticFile, useCurrentFrame} from 'remotion';
import {LINES, VOICE_END} from './assistantTimings';

export const FPS = 30;
const LEAD = 12; // 0.4s before the voice starts
const FREEZE = LEAD + Math.round(VOICE_END * FPS); // last frame with any motion
export const ASSISTANT_DURATION = FREEZE + 2 * FPS; // hold 2s after the voice ends

const BLUE = '#1A6DE0';
const ORANGE = '#F7941D';
const GREEN = '#17A06A';
const RED = '#E5484D';
const PURPLE = '#7C4DDB';
const INK = '#14213D';
const FONT = 'Inter, "Inter Display", system-ui, sans-serif';

const COL_LEFT = 110;
const COL_WIDTH = 780; // x 110-890, inside the 80-920 safe area

const lineStartF = (i: number) => LEAD + Math.round(LINES[i].start * FPS);
const wordStartF = (i: number, w: number) => LEAD + Math.round(LINES[i].words[w].start * FPS);

type Scene = {from: number; to: number; bg: [string, string, string?]; angle: number};
const sceneFrom = (i: number) => (i === 0 ? 0 : lineStartF(i) - 5);
const SCENES: Scene[] = [
  {bg: [BLUE, '#5B4FE0', '#8B5CF6'], angle: 160},
  {bg: [ORANGE, '#F26B1D', '#D9480F'], angle: 160},
  {bg: ['#F0595C', '#D9363E', '#A61E2C'], angle: 160},
  {bg: ['#9B6BF7', '#7C4DDB', '#4F34B8'], angle: 160},
  {bg: ['#2CC08A', '#17A06A', '#0B6E64'], angle: 160},
  {bg: [BLUE, '#1557C0', '#0A3D9E'], angle: 160},
  {bg: [BLUE, '#4B5BDC', ORANGE], angle: 150},
].map((s, i) => ({...s, from: sceneFrom(i), to: i === 6 ? ASSISTANT_DURATION : sceneFrom(i + 1)})) as Scene[];

const ease = Easing.out(Easing.cubic);
const enter = (f: number, start: number, dur = 9) =>
  interpolate(f, [start, start + dur], [0, 1], {easing: ease, extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});

/* ---------- backgrounds (full bleed, no content) ---------- */

const Backgrounds: React.FC<{f: number}> = ({f}) => (
  <AbsoluteFill>
    {SCENES.map((s, i) => {
      const opacity = i === 0 ? 1 : interpolate(f, [s.from, s.from + 7], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
      if (f < s.from) return null;
      const angle = s.angle + Math.sin(f / 45) * 6;
      return (
        <AbsoluteFill
          key={i}
          style={{opacity, background: `linear-gradient(${angle}deg, ${s.bg.filter(Boolean).join(', ')})`}}
        />
      );
    })}
    {[
      {x: 120, y: 330, r: 300, c: '#FFFFFF', o: 0.1, sp: 70},
      {x: 930, y: 1000, r: 380, c: '#FFFFFF', o: 0.08, sp: 90},
      {x: 200, y: 1700, r: 340, c: '#FFD9A0', o: 0.14, sp: 80},
      {x: 900, y: 120, r: 220, c: '#FFD9A0', o: 0.12, sp: 60},
    ].map((d, i) => (
      <div
        key={i}
        style={{
          position: 'absolute',
          left: d.x - d.r + Math.sin(f / d.sp + i) * 40,
          top: d.y - d.r + Math.cos(f / d.sp + i * 2) * 40,
          width: d.r * 2,
          height: d.r * 2,
          borderRadius: '50%',
          background: d.c,
          opacity: d.o,
        }}
      />
    ))}
  </AbsoluteFill>
);

/* ---------- small pieces ---------- */

